package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;

/**
 * Assigns the owner's deterministic {@code householdId}: the first 12 hex characters of SHA-256 over
 * the normalized last name and postcode (see {@link OwnerIdentityKey#householdId(String, String)}).
 * Every owner receives one, so owners sharing a last name and postcode automatically share the id —
 * there is no explicit linking and no dependency on {@code sharesHousehold} (that flag now only
 * bypasses the household duplicate block in {@link EnsureUniqueIdentity}).
 *
 * <p>Runs after {@link BuildOwner} within the create transaction and before {@link AssignHouseholdSize},
 * which counts the members sharing this computed id, and {@link SaveOwner}, which persists it.
 */
public class AssignHousehold {

    public void service(@Val Owner owner) {
        owner.setHouseholdId(HouseholdId.of(owner));
    }
}

package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;

/**
 * Records, on the owner being created, the size of its household — the number of owners sharing the
 * same deterministic {@code householdId} once this create completes. The id is keyed on
 * {@code (normalizedLastName, postcode)} (see {@link OwnerIdentityKey}), so this counts existing owners
 * with the same last name and postcode plus one for the owner being created (not yet saved).
 *
 * <p>Runs after {@link AssignHousehold}, which has set the new owner's {@code householdId}, and before
 * {@link SaveOwner}.
 */
public class AssignHouseholdSize {

    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
        String householdId = owner.getHouseholdId();
        int count = 1; // the owner being created, not yet saved
        for (Owner existing : ownerRepository.findAll()) {
            if (householdId.equals(HouseholdId.of(existing))) {
                count++;
            }
        }
        owner.setHouseholdSize(count);
    }
}

package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;

/**
 * Caps, on the owner being created, its {@code membershipLevel} so it cannot exceed one above the
 * current maximum {@code membershipLevel} among the existing members of its household — the owners
 * already saved that share the same deterministic {@code householdId} (see {@link OwnerIdentityKey}).
 * With no existing household member no cap applies and the level assigned by
 * {@link AssignMembershipLevel} stands.
 *
 * <p>Runs after {@link AssignMembershipLevel}, which has set the raw level, and before
 * {@link SaveOwner} persists it.
 */
public class CapMembershipLevel {

    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
        Integer level = owner.getMembershipLevel();
        if (level == null) {
            return;
        }
        String householdId = owner.getHouseholdId();
        Integer maxExisting = null;
        for (Owner existing : ownerRepository.findAll()) {
            if (householdId.equals(HouseholdId.of(existing))
                    && existing.getMembershipLevel() != null
                    && (maxExisting == null || existing.getMembershipLevel() > maxExisting)) {
                maxExisting = existing.getMembershipLevel();
            }
        }
        if (maxExisting != null && level > maxExisting + 1) {
            owner.setMembershipLevel(maxExisting + 1);
        }
    }
}
